def _merge_tokens(name):
    s = "".join(ch for ch in unicodedata.normalize("NFKD", name or "") if not unicodedata.combining(ch))
    s = re.sub(r"(\w)['’]s\b", r"\1", s)                       # possessive, not 'south'
    s = re.sub(r"\b(\d+)(?:st|nd|rd|th)\b", r"\1", s, flags=re.I)   # 4th -> 4
    t = [_MERGE_ABBR.get(w, w) for w in re.findall(r"[a-z0-9]+", s.lower().replace("&", " and "))]
    return {w for w in t if w not in _MERGE_GENERIC}

def _same_station(d, name, fid, other, R_SAME=150.0, R_NAMED=300.0, pid="", okey=None):
    if d <= R_SAME: return True
    if d > R_NAMED: return False
    if okey and okey[0] == str(fid) and okey[1] and pid and okey[1] != pid:
        return False   # two parent stations of one feed are two stations (NYCT 50 St 126 / A25)
    if str(fid) == "11": return True
    a, b = _merge_tokens(name), _merge_tokens(other)
    if {w for w in a if w.isdigit()} != {w for w in b if w.isdigit()}:
        return False   # '7 Av' is not '57 St-7 Av'
    return bool(a and b) and len(a & b) / len(a | b) >= 0.5

